["311"] = {
["Title"]="Return to Marleth",
["Description"]="Dopo aver inserito un barile di Marleth's Scalder nella cantina della Kharanos Distillery, tu afferri un barile di Thunder Ale come prova del fatto....",
["Objectives"]="Porta il barile di Thunder Ale a Marleth Barleybrew al Brewnall Village.",
["Progress"]="Hai eseguito le mie istruzioni?",
["Completion"]="Niente male, YOUR_NAME! Hai avuto problemi nel passare le guardie?NEW_LINENEW_LINENon importa - molte grazie, e se avrai bisogno di un aiuto, vieni dai Barleybrews!",
["minlevel"]="7",
["questlevel"]="6",
