["questlevel"]="68",
}, -- end A Carefully Wrapped Present

-- A Festive Gift
["8803"] = {
["Title"]="A Festive Gift",
["Description"]="",
["Objectives"]="",
["Progress"]="",
["Completion"]="La nota che leggi sul regalo dice:NEW_LINENEW_LINEA YOUR_NAME, NEW_LINENEW_LINESperando che questo presente ti aiuti a diffondere la buona novella e allietare le vacanze ad Azeroth. NEW_LINENEW_LINEDa Babbo Natale.",
["minlevel"]="10",
