["1843"] = {
["Title"]="Brutal Gauntlets",
["Description"]="",
["Objectives"]="",
["Progress"]="",
["Completion"]="Grazie, YOUR_NAME. Questi guanti sono il mio miglior lavoro. Prendili. Indossandoli, porterai onore a me e ai miei antenati.",
["minlevel"]="30",
