}, -- end Allegiance to Cenarion Circle

-- A Thief's Reward
["9339"] = {
["Title"]="A Thief's Reward",
["Description"]="",
["Objectives"]="",
["Progress"]="",
["Completion"]="Hai dato prova di te stesso, oggi, YOUR_NAME.NEW_LINENEW_LINEHo molto poco altro da darti, ma ho questa corona; una ricompensa adatta ad un conquistatore. Possa illuminare la tua strada.",
["minlevel"]="60",
