["12567"] = {
["Title"]="Blessing of Zim'Abwa",
["Description"]="",
["Objectives"]="",
["Progress"]="<Il viso di pietra di Zim'Abwa penetra la tua anima.NEW_LINENEW_LINEZim'Abwa è soddisfatto, ma desidera che tu mostri ulteriore apprezzamento e rispetto donandogli altre Drakkari offerings.NEW_LINENEW_LINETi ricompenserà in natura.>",
["Completion"]="<Avverti l'approvazione di Zim'Abwa. In qualche modo, sai che Zim'Abwa desidera altri tributi!>",
["minlevel"]="76",
